import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl, setCameraLimits } from "@babylonjs/lite";

export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  const detachControl = attachControl(camera, canvas, scene);
  const detachLimits = setCameraLimits(
    camera,
    { lowerRadiusLimit: minDistance, upperRadiusLimit: maxDistance },
    scene
  );

  return () => {
    detachControl();
    detachLimits();
  };
}
```

I attached the library's standard arc-rotate controls via `attachControl` (which gives drag-to-orbit, wheel zoom, and pinch zoom) and then applied `setCameraLimits` with the radius bounds, which clamps the pose immediately and clamps every subsequent radius write in-statement—covering both the inertial wheel path and the direct pinch write. The returned function calls both disposes to remove all canvas listeners and per-frame hooks. I'm confident in this; the only minor uncertainty is whether `attachControl` and `setCameraLimits` are exported at the package root (`@babylonjs/lite`) versus a sub-path, but given the type declarations are bundled together and the user specified that import name, that's the natural assumption.
